package com.opensocket.aievent.database.persistence.issueprojection;
import java.time.OffsetDateTime; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.integration.issue.projection.*; import com.opensocket.aievent.core.issuetracking.contract.ProjectionLifecycleStatus; import com.opensocket.aievent.database.persistence.issueprojection.dao.IssueProjectionStateDao; import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;
@DatabaseRepositoryAdapter @ConditionalOnProperty(prefix="issue-projection",name="store",havingValue="MYBATIS")
public class MybatisIssueProjectionStateRepository implements IssueProjectionStateRepository {
 private final IssueProjectionStateDao dao; private final IssueProjectionPersistenceConverter c; public MybatisIssueProjectionStateRepository(IssueProjectionStateDao dao,IssueProjectionPersistenceConverter c){this.dao=dao;this.c=c;}
 public IssueProjectionState save(IssueProjectionState v){var old=dao.find(v.tenantId(),v.projectionId());if(old==null)dao.insertState(c.toPo(v));else if(dao.updateStateCas(c.toPo(v),old.getVersion())!=1)throw new IllegalStateException("RESOURCE_VERSION_CONFLICT: issue projection");return find(v.tenantId(),v.projectionId()).orElse(v);} public Optional<IssueProjectionState> find(String t,String id){return Optional.ofNullable(dao.find(t,id)).map(c::state);} public Optional<IssueProjectionState> findByAggregateKey(String t,String k){return Optional.ofNullable(dao.findByAggregateKey(t,k)).map(c::state);} public Optional<IssueProjectionState> findBySourceEvent(String t,String id){return Optional.ofNullable(dao.findBySourceEvent(t,id)).map(c::state);} public Optional<IssueProjectionState> findByTaskIssueLink(String t,String id){return Optional.ofNullable(dao.findByTaskIssueLink(t,id)).map(c::state);} public Optional<IssueProjectionState> findLatestByTask(String t,String id){return Optional.ofNullable(dao.findLatestByTask(t,id)).map(c::state);} public List<IssueProjectionState> list(String t,ProjectionLifecycleStatus state,int n){return dao.list(t,state==null?null:state.name(),n).stream().map(c::state).toList();} public List<IssueProjectionState> listDue(OffsetDateTime now,int n){return dao.listDue(now,n).stream().map(c::state).toList();} public boolean tryRecordDomainEvent(String t,String p,String e,long s,String h,OffsetDateTime a){return dao.insertEventReceipt(t,p,e,s,h,a)==1;}
 public IssueProjectionReconciliationCase saveCase(IssueProjectionReconciliationCase v){var old=dao.findCase(v.tenantId(),v.caseId());if(old==null)dao.insertCase(c.toPo(v));else dao.updateCase(c.toPo(v));return findCase(v.tenantId(),v.caseId()).orElse(v);} public Optional<IssueProjectionReconciliationCase> findCase(String t,String id){return Optional.ofNullable(dao.findCase(t,id)).map(c::reconciliation);} public Optional<IssueProjectionReconciliationCase> findOpenCaseByProjection(String t,String id){return Optional.ofNullable(dao.findOpenCaseByProjection(t,id)).map(c::reconciliation);} public List<IssueProjectionReconciliationCase> listCases(String t,IssueProjectionReconciliationStatus status,int n){return dao.listCases(t,status==null?null:status.name(),n).stream().map(c::reconciliation).toList();} public String mode(){return "MYBATIS";}
}
